import * as THREE from'three';import{autoFitOrthographicBounds}from'../camera-fit.js';import{createToyKit,disposeToyTree}from'../world/toy-kit.js';import{RACE_START,RACE_LANES,RACE_DISTANCE,RACE_FLOOR}from'./race-model.js';
export function createRaceSession({view,player,model,poser}){
 if(!view?.root||!player||!model||!poser)throw Error('Race actors unavailable');const root=view.root;
 const saved={position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),pose:poser.getState(),children:player.children.map(n=>[n,n.visible]),background:[root.getObjectByName('sportsField.passing-entry'),root.getObjectByName('sportsField.passing-pad'),root.getObjectByName('sportsField.race-entry'),root.getObjectByName('sportsField.ball'),view.schoolView?.throwCourt?.root,...root.children.filter(n=>n.userData.species==='athletic-turtle')].filter(Boolean).map(n=>[n,n.visible])};
 const lease=view.acquireResidentActivity?.('athletic-rabbit');if(!lease)throw Error('Race friend unavailable');let alive=true;
 function place(x,z){root.updateWorldMatrix(true,false);const p=root.localToWorld(new THREE.Vector3(x,RACE_FLOOR,z));if(player.parent)player.parent.worldToLocal(p);player.position.copy(p);const q=root.getWorldQuaternion(new THREE.Quaternion()).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),Math.PI/2));if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);}
 function update(s,reduced=false){if(!alive)return;const moving=s.phase==='running'&&!s.paused,playerRun=moving&&s.playerFinish===null,rabbitRun=moving&&s.rabbitFinish===null;place(RACE_START+s.playerDistance,RACE_LANES.player);model.position.set(0,0,0);model.quaternion.identity();poser.setPose(playerRun&&!reduced?'run':'stand',1,reduced?0:s.playerDistance/.30*Math.PI*2/8);lease.pose({x:RACE_START+s.rabbitDistance,z:RACE_LANES.rabbit,y:RACE_FLOOR,yaw:Math.PI/2,walking:rabbitRun&&!reduced,running:rabbitRun&&!reduced,holding:false,showBall:false,time:s.rabbitDistance/.4*Math.PI*2/8});player.updateWorldMatrix(true,true);}
 function dispose(){if(!alive)return;alive=false;lease.release();player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);try{poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);}finally{for(const[n,v]of saved.children)n.visible=v;for(const[n,v]of saved.background)n.visible=v;player.updateWorldMatrix(true,true);}}
 try{for(const[n]of saved.background)n.visible=false;for(const[n]of saved.children)if(n!==model)n.visible=false;player.scale.setScalar(1);model.scale.setScalar(1);update({phase:'ready',playerDistance:0,rabbitDistance:0,playerFinish:null,rabbitFinish:null});}catch(e){dispose();throw e;}
 return{update,dispose,rabbitUUID:lease.model.uuid};
}
export function createRaceView(parent){const root=new THREE.Group();root.name='sportsField.race';parent.add(root);const kit=createToyKit(root);for(const[who,z]of Object.entries(RACE_LANES)){kit.box(RACE_DISTANCE+1.4,.018,1.12,who==='player'?'#ddd1aa':'#b6d1b2',0,.065,z,.025);for(let x=RACE_START;x<=-RACE_START;x+=.8)kit.box(.37,.002,.025,'#fff8df',x,.075,z-.56,.001);for(const x of[RACE_START,-RACE_START])for(let j=0;j<4;j++)kit.box(.10,.002,.25,j%2?'#526f67':'#fff8df',x,.076,z-.375+j*.25,.001);}
 for(const z of[2.37,5.38]){kit.cylinder(.027,.027,1.15,'#779387',5.55,.63,z);kit.box(.42,.28,.055,'#edc776',5.75,1.1,z,.045);}
 let disposed=false;return{root,update(){},dispose(){if(!disposed){disposed=true;disposeToyTree(root);}}};}
export function fitRaceCamera(camera,root,viewport,s){root.updateWorldMatrix(true,false);const px=RACE_START+s.playerDistance,rx=RACE_START+s.rabbitDistance,center=(px+rx)/2;camera.position.copy(root.localToWorld(new THREE.Vector3(center,7.2,12.5)));camera.up.set(0,1,0);camera.lookAt(root.localToWorld(new THREE.Vector3(center,1,3.9)));camera.updateMatrixWorld(true);const b=new THREE.Box3(new THREE.Vector3(Math.min(center-2.6,px-.85,rx-.85),.01,2.5),new THREE.Vector3(Math.max(center+2.6,px+.85,rx+.85),2.5,5.3)).applyMatrix4(root.matrixWorld);autoFitOrthographicBounds({camera,worldBounds:b,viewport,paddingPx:{top:12,right:12,bottom:12,left:12}});camera.updateMatrixWorld(true);return b;}
